 start_x=page.locator('#actor').bounding_box()['x'];page.locator('#code').fill('farm_name = "Willow Farm"');page.locator('#run').click();page.wait_for_function("document.getElementById('actor').dataset.state==='walking'");samples=page.evaluate('''()=>new Promise(resolve=>{const data=[];function frame(t){const a=document.getElementById('actor');data.push({t,x:a.getBoundingClientRect().x,facing:getComputedStyle(document.getElementById('facing')).transform,mix:parseFloat(document.getElementById('walkA').style.opacity||0)+parseFloat(document.getElementById('walkB').style.opacity||0)});if(a.dataset.state!=='walking'||data.length>240)resolve(data);else requestAnimationFrame(frame)}requestAnimationFrame(frame)})''');assert len(samples)>12;assert all(b['x']>=a['x']-.1 for a,b in zip(samples,samples[1:]));speeds=[(b['x']-a['x'])/((b['t']-a['t'])/1000) for a,b in zip(samples,samples[1:]) if b['t']>a['t']];assert max(speeds)<500;assert max(speeds[:3])<max(speeds)*.8;assert max(speeds[-3:])<max(speeds)*.8;assert any(x['mix']>.5 for x in samples);assert all(not x['facing'].startswith('matrix(-') for x in samples);mid_x=samples[len(samples)//2]['x'];assert mid_x>start_x+1;assert page.locator('#continue').is_disabled();page.wait_for_function("document.getElementById('actor').dataset.state==='acting'");assert page.locator('#actor').bounding_box()['x']>mid_x+1;assert page.locator('#signText').text_content()==''
 page.wait_for_function("document.getElementById('actor').dataset.state==='complete'");assert not page.locator('#facing').evaluate("e=>getComputedStyle(e).transform.startsWith('matrix(-')");assert page.locator('#actor').bounding_box()['x']+page.locator('#actor').bounding_box()['width']<=page.locator('#signText').bounding_box()['x'];assert page.locator('#signText').text_content()=='Willow Farm';assert page.locator('#xpMeter').text_content()=='✦ 50 XP';assert page.locator('#run').is_disabled();assert not page.locator('#continue').is_disabled();page.screenshot(path='/tmp/mochi-fluid-complete-phone.png')
 page.locator('#continue').click();assert page.locator('#chapterComplete').is_visible();assert 'Willow Farm' in page.locator('#completeCopy').text_content();page.locator('#closeComplete').click()
 # Reset during a walk cannot apply the canceled run or award XP.
 page.locator('#reset').click();page.wait_for_function("document.getElementById('actor').dataset.state==='idle'");page.locator('#run').click();page.wait_for_function("document.getElementById('actor').dataset.state==='walking'");page.locator('#reset').click();page.wait_for_function("document.getElementById('actor').dataset.state==='idle'");page.wait_for_timeout(1700);assert page.locator('#signText').text_content()=='';assert page.locator('#xpMeter').text_content()=='✦ 0 XP'
 page.emulate_media(reduced_motion='reduce');page.locator('#code').fill('farm_name = "<img src=x onerror=alert(1)>"');page.locator('#run').click();page.wait_for_function("document.getElementById('actor').dataset.state==='complete'");assert not page.locator('#facing').evaluate("e=>getComputedStyle(e).transform.startsWith('matrix(-')");assert page.locator('#signText img').count()==0;assert '<img' in page.locator('#signText').text_content()
 for width,height,name in [(320,740,'small-phone'),(390,844,'phone'),(820,1180,'tablet'),(1440,1000,'desktop'),(844,390,'landscape')]:
  page.set_viewport_size({'width':width,'height':height});page.wait_for_function('parseFloat(document.documentElement.style.getPropertyValue("--viewport-height"))===innerHeight');page.evaluate('()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');sizes=page.evaluate('''()=>({scene:document.getElementById('scene').clientHeight,total:document.querySelector('.game').clientHeight,panel:document.querySelector('.editor-panel').clientHeight,overflow:document.documentElement.scrollWidth>innerWidth})''');assert abs(sizes['scene']/sizes['total']-.7)<.005,(name,sizes);assert not sizes['overflow'];page.screenshot(path=f'/tmp/mochi-fluid-{name}.png')
 assert not errors,errors;assert not remote,remote
